INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26201, 'Acts 11:23', 'Acts', 11, 23, '&nbsp;کله چې هغه راورسېدو او د خُدائ پاک فضل يې وليدو هغه ډېر خوشحاله شو او هغوئ ټولو ته يې ډاډګيرنه ورکړه او ورته يې ووئيل چې مالِک سره په وفادارۍ او په پوره زړۀ ټينګ ودرېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26202, 'Acts 11:24', 'Acts', 11, 24, '&nbsp;برنباس يو ښۀ سړے وو د روحُ القُدس نه معمور او ايمان يې مضبوط وو. او ډېرو خلقو په مالِک باندې ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26203, 'Acts 11:25', 'Acts', 11, 25, '&nbsp;بيا برنباس ترسس ته لاړو چې ساؤل پېدا کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26204, 'Acts 11:26', 'Acts', 11, 26, '&nbsp;کله چې يې هغه پېدا کړو نو هغه يې اَنطاکيه ته ولېږلو او پوره يو کال برنباس او ساؤل په شريکه د جماعت خِدمت کولو او ډېرو خلقو له يې تعليم ورکولو. په اَنطاکيه کښې مريدانو ته په اول ځل عيسايان ووئيلے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26205, 'Acts 11:27', 'Acts', 11, 27, '&nbsp;په هغه وخت کښې څۀ نبيان د يروشلم نه اَنطاکيه ته راغلل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26206, 'Acts 11:28', 'Acts', 11, 28, '&nbsp;چې په هغوئ کښې د يو نوم اګابوس وو، هغه ودرېدو او د روحُ القُدس په وسيله يې پېشګوئې وکړه چې په ټوله دُنيا کښې به يو سخت قحط راشى. او دا قحط د قيصر کلوديوس په بادشاهۍ کښې راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26207, 'Acts 11:29', 'Acts', 11, 29, '&nbsp;نو مريدانو فېصله وکړه چې هر يو به د خپل طاقت په مطابق هغه ايماندارانو له امداد ورلېږى چې په يهوديه کښې اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26208, 'Acts 11:30', 'Acts', 11, 30, '&nbsp;هغوئ چنده وکړه او مشرانو له يې د برنباس او ساؤل په ذريعه ورولېږله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26209, 'Acts 12:1', 'Acts', 12, 1, '&nbsp;تقريباً هم په هغه وخت هيروديس بادشاه د جماعت څۀ خلق ونيول او ظلم زياتے يې ورسره شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26210, 'Acts 12:2', 'Acts', 12, 2, '&nbsp;هغۀ د يوحنا ورور يعقوب په تُوره شهيد کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26211, 'Acts 12:3', 'Acts', 12, 3, '&nbsp;نو کله چې هغه خبر شو چې يهوديان په دې کار خوشحاله شول، نو پطروس يې هم ګرفتار کړو. دا واقعه د پتيرې روټۍ د اختر په ورځو کښې وشوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26212, 'Acts 12:4', 'Acts', 12, 4, '&nbsp;د ګرفتارولو نه وروستو يې هغه په قېد کښې واچولو او د سپاهيانو څلور ډلو ته يې حواله کړو چې د دۀ څوکيدارى کوى. د هيروديس دا خيال وو چې د فسح د اختر نه وروستو به يې د خلقو په وړاندې فېصله واوروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26213, 'Acts 12:5', 'Acts', 12, 5, '&nbsp;نو هغۀ پطروس په قېدخانه کښې وساتلو، خو جماعت د پطروس دپاره په جوش سره د خُدائ پاک نه دُعا غوښتله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26214, 'Acts 12:6', 'Acts', 12, 6, '&nbsp;په هم هغه شپه هيروديس د پطروس د بهر راوستو نه وړاندې هغه د دوو سپاهيانو په مينځ کښې په دوو زنځيرونو تړلے اودۀ پروت وو او د دروازې نه بهر څوکيدارانو د قېدخانې څوکۍ کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26215, 'Acts 12:7', 'Acts', 12, 7, '&nbsp;چې ناڅاپى د مالِک خُدائ يوه فرښته هلته ودرېده او په کوټڼۍ کښې رڼا وځلېده. هغې د پطروس اوږه وخوځوله او راويښ يې کړو او ورته يې وفرمائيل، ”زر شه، راپاڅه.“ نو په دې کښې زولنۍ د پطروس د مړوندونو نه وغورزېدلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26216, 'Acts 12:8', 'Acts', 12, 8, '&nbsp;بيا فرښتې هغۀ ته ووئيل چې، ”ملابند وتړه او خپل پېزار په پښو کړه.“ پطروس هم هغه شان وکړل. بيا فرښتې هغۀ ته ووئيل، ”خپله چُوغه واچوه او ما پسې راځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26217, 'Acts 12:9', 'Acts', 12, 9, '&nbsp;پطروس د کوټڼۍ نه بهر فرښتې پسې نېغ روان وو، خو د هغۀ دا خيال نۀ وو چې ګنې دا رښتيا دى خو د هغۀ سوچ دا وو چې دا ګنې خوب دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26218, 'Acts 12:10', 'Acts', 12, 10, '&nbsp;هغوئ د وړومبې او دوېمې څوکۍ نه واوړېدل او د اوسپنې هغه دروازې ته راورسېدل کومه چې ښار ته وتې وه. دا د هغوئ دپاره په خپله کولاو شوه او دوئ ترې نه ووتل. کله چې هغوئ په کوڅه کښې روان وُو نو څۀ ګورې چې فرښته د هغۀ سره نۀ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26219, 'Acts 12:11', 'Acts', 12, 11, '&nbsp;بيا پطروس په خود کښې راغلو او هغۀ خپل ځان سره ووئيل چې، ”اوس زما پوره يقين دے چې مالِک خُدائ خپله فرښته ما ته رالېږلې ده او ما ته يې د هيروديس او د يهوديانو د ټولو بدو منصوبو نه نجات راکړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26220, 'Acts 12:12', 'Acts', 12, 12, '&nbsp;کله چې هغه په دې پوهه شو نو بيا هغه د مريم کور ته لاړو چې د يوحنا مرقوس مور وه. هلته ډېر ګڼ خلق راغونډ شوى وُو او دُعا يې کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26221, 'Acts 12:13', 'Acts', 12, 13, '&nbsp;کله چې پطروس بهر دروازه وټکوله نو روده نومې نوکره دروازې ته ورغله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26222, 'Acts 12:14', 'Acts', 12, 14, '&nbsp;نو چې هغې د پطروس آواز وپېژندلو هغه دومره خوشحاله شوه چې د دروازې خلاصولو په ځائ هغې دننه منډه کړه او هغوئ يې خبر کړل چې، ”پطروس بهر په دروازه کښې ولاړ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26223, 'Acts 12:15', 'Acts', 12, 15, '&nbsp;هغوئ هغې ته ووئيل چې، ”تۀ ليونۍ يې.“ خو هغه په خپله خبره ټينګه وه چې زۀ رښتيا وايم. خو هغوئ ووئيل چې، ”دا به ضرور د هغۀ فرښته وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26224, 'Acts 12:16', 'Acts', 12, 16, '&nbsp;خو پطروس هم هغه شان دروازه ټکوله او چې کله هغوئ دروازه کولاو کړه نو بيا د هغۀ په ليدو حق حېران شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26225, 'Acts 12:17', 'Acts', 12, 17, '&nbsp;خو پطروس هغوئ ته د چپ کېدو اِشاره وکړه او ټوله قيصه يې ورته بيان کړه چې مالِک هغه څنګه د قېدخانې نه بهر راوويستو. نو بيا هغۀ ووئيل چې، ”يعقوب او زمونږ نور وروڼه په دې واقعه خبر کړئ.“ او بيا هغه بل ځائ ته روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26226, 'Acts 12:18', 'Acts', 12, 18, '&nbsp;چې سحر شو نو سپاهيان په دې ډېر پرېشانه وُو چې پطروس څۀ شو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26227, 'Acts 12:19', 'Acts', 12, 19, '&nbsp;کله چې هيروديس هغه ښۀ ولټولو او پېدا يې نۀ کړو، بيا هغۀ د سپاهيانو نه بيان واخستو او د هغوئ د وژلو حُکم يې ورکړو. د دې نه پس هيروديس د يهوديه نه لاړو او د څۀ وخت دپاره په قيصريه کښې پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26228, 'Acts 12:20', 'Acts', 12, 20, '&nbsp;نو هيروديس د صور او د صيدا خلقو ته په قهر وو نو په دې وجه هغوئ ورته د صلحې دپاره جرګه ورولېږله ځکه چې د هغوئ ښارونه د خوراک دپاره د هيروديس د مُلک محتاجه وُو. د سفارش کولو دپاره جرګې خپل ځان سره د بادشاه د دربار ناظر بلستوس ملګرے کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26229, 'Acts 12:21', 'Acts', 12, 21, '&nbsp;نو په يوه مقرره ورځ هيروديس خپل شاهى لباس واچولو، او په تخت کښېناستو او هغوئ ته يې تقرير شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26230, 'Acts 12:22', 'Acts', 12, 22, '&nbsp;او ګڼې چغې وهلې چې، ”دا خو د خُدائ آواز دے، نه چې د انسان.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26231, 'Acts 12:23', 'Acts', 12, 23, '&nbsp;نو سمدستى د مالِک خُدائ يوې فرښتې هيروديس ووهلو، ځکه چې هغۀ د خُدائ پاک تمجيد ونۀ کړو، او هغه چينجو وخوړو او مړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26232, 'Acts 12:24', 'Acts', 12, 24, '&nbsp;خو په هم دې وخت کښې د خُدائ پاک کلام خورېدلو او ترقى يې کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26233, 'Acts 12:25', 'Acts', 12, 25, '&nbsp;بيا برنباس او ساؤل د خپل خِدمت پوره کولو نه پس يروشلم ته واپس راغلل، او ځان سره يې يوحنا راوستو، چې بل نوم يې مرقوس وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26234, 'Acts 13:1', 'Acts', 13, 1, '&nbsp;د اَنطاکيه په جماعت کښې نبيان او اُستاذان وُو، برنباس، شمعون چې په تور ياديږى، لوکيوس کرينى، مناهين چې د هيروديس حاکِم سره يو ځائ لوئ شوے وو، او ساؤل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26235, 'Acts 13:2', 'Acts', 13, 2, '&nbsp;کله چې هغوئ د مالِک عبادت کولو او روژه يې نيولې وه نو روحُ القُدس ورته وفرمائيل، ”برنباس او ساؤل زما د هغه کار دپاره منتخب کړئ د څۀ دپاره چې ما هغوئ رابللى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26236, 'Acts 13:3', 'Acts', 13, 3, '&nbsp;نو د روژې نيولو او دُعا کولو نه پس هغوئ د برنباس او ساؤل په سر خپل لاسونه کېښودل او رُخصت يې کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26237, 'Acts 13:4', 'Acts', 13, 4, '&nbsp;هغوئ دواړه د روحُ القُدس په وسيله ولېږلے شول، او هغوئ سلوکيه ته ښکته لاړل او بيا د هلته نه په سمندرى جهاز کښې قبرص ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26238, 'Acts 13:5', 'Acts', 13, 5, '&nbsp;کله چې هغوئ سَلميس ته راورسېدل نو هغوئ د خُدائ پاک کلام د يهوديانو په عبادتخانو کښې واورولو او د هغوئ سره يوحنا هم د مددګار په توګه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26239, 'Acts 13:6', 'Acts', 13, 6, '&nbsp;هغوئ تر پافُس پورې په ټوله جزيره کښې وګرځېدل. هلته هغوئ يو يهودى جادوګر سره مِلاو شول، چې د دروغو نبى وو او نوم يې بريسوع وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26240, 'Acts 13:7', 'Acts', 13, 7, '&nbsp;هغه د سرګيوس پولوس ګورنر ملګرے وو. ګورنر يو هوښيار سړے وو. هغۀ برنباس او ساؤل راوبلل ځکه چې هغۀ غوښتل چې د خُدائ پاک کلام واورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26241, 'Acts 13:8', 'Acts', 13, 8, '&nbsp;خو جادوګر چې په يونانۍ کښې ورته اِليماس وائى، د هغوئ مخالفت وکړو او دا کوشش يې کولو چې ګورنر ايمان رانۀ وړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26242, 'Acts 13:9', 'Acts', 13, 9, '&nbsp;خو ساؤل چې ورته پولوس هم وائى د روحُ القُدس نه معمور وو، اِليماس ته يې نېغ کتل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26243, 'Acts 13:10', 'Acts', 13, 10, '&nbsp;او ورته يې ووئيل چې، ”اے د اِبليس زويه، اے د صداقت دشمنه، اے ټګه او د شرارت نه ډکه. ولې تۀ د مالِک د نېغو لارو د کږولو نه نۀ منع کيږى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26244, 'Acts 13:11', 'Acts', 13, 11, '&nbsp;خو ګوره اوس، مالِک خُدائ ستا خلاف شو. تۀ به ړوند شې او د څۀ وخت پورې به تۀ د نمر رڼا نۀ وينې.“ سمدستى د هغۀ په سترګو خړه راغله او په ټَپو شو او بيا هغۀ لاسونه ټپول چې د لاس نه يې څوک ونيسى او بو يې ځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26245, 'Acts 13:12', 'Acts', 13, 12, '&nbsp;کله چې ګورنر دا هر څۀ وليدل نو ايمان يې راوړو، ځکه چې هغه د مالِک په حقله د تعليم په وجه ډېر متاثره شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26246, 'Acts 13:13', 'Acts', 13, 13, '&nbsp;پولوس او د هغۀ ملګرى د پافُس نه په سمندرى جهاز کښې پرګې ته لاړل چې په پمفوليه کښې ده. نو يوحنا ترې جدا شو او يروشلم ته واپس لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
